from sympy import symbols, integrate, expand, sqrt, exp, log, pi, Rational
import math

x = symbols("x", real=True)

def washer_line(m, k):
    top, bottom = m*x, x**2
    if k <= 0:
        R, r = top - k, bottom - k
    else:
        R, r = k - bottom, k - top
    print(f"  y = {top} and y = {bottom} meet at x = 0 and {m}, spun around y = {k}")
    print(f"  R = {R}, r = {r}: V = pi * {integrate(expand(R**2 - r**2), (x, 0, m))} = {pi * integrate(expand(R**2 - r**2), (x, 0, m))}")

def shell_line(m, h):
    height = m*x - x**2
    if h <= 0:
        radius = x - h
    else:
        radius = h - x
    print(f"  height {height}, radius {radius} from the line x = {h}")
    print(f"  V = 2*pi * {integrate(expand(radius * height), (x, 0, m))} = {2 * pi * integrate(expand(radius * height), (x, 0, m))}")

def moments(n, b):
    f = (n + 1) * x**n / b**(n + 1)
    mu = integrate(x * f, (x, 0, b))
    var = integrate(x**2 * f, (x, 0, b)) - mu**2
    print(f"  f = {f} on [0, {b}]: mu = integral of x f = {mu}")
    print(f"  Var = integral of x^2 f - mu^2 = {var}, sigma = {sqrt(var)}, about {float(sqrt(var)):.4f}")

def cool(T0, Ts, t1, T1, target):
    k = math.log((T0 - Ts) / (T1 - Ts)) / t1
    t = math.log((T0 - Ts) / (target - Ts)) / k
    print(f"  the gap {T0 - Ts} shrinks to {T1 - Ts} in {t1}: k = ln({(T0 - Ts) / (T1 - Ts)})/{t1} = {k:.4f}")
    print(f"  the gap reaches {target - Ts} at t = ln({(T0 - Ts) / (target - Ts)})/k = {t:.2f}")

def euler(k, y0, h, n):
    y = y0
    for i in range(n):
        y = y + h * k * y
        print(f"  x = {(i + 1) * h}: y = {y}, about {float(y):.4f}")
    print(f"  exact y0 e^(kx) = {float(y0) * math.exp(k * n * h):.4f}")

def run(kind, nums):
    if kind == "washer_line":
        washer_line(nums[0], nums[1])
    elif kind == "shell_line":
        shell_line(nums[0], nums[1])
    elif kind == "moments":
        moments(nums[0], nums[1])
    elif kind == "cool":
        cool(nums[0], nums[1], nums[2], nums[3], nums[4])
    else:
        euler(nums[0], nums[1], nums[2], int(nums[3]))

problems = [("washer_line", [2, -1]), ("shell_line", [2, 3]), ("moments", [1, 2]), ("cool", [90, 20, 5, 80, 40]),
    ("euler", ["1/2", 2, "1/2", 4]), ("washer_line", [1, 1]), ("shell_line", [1, -2]), ("moments", [0, 6]), ("euler", [-1, 1, "1/4", 4])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

